import MenuCard from "./MenuCard";

const MENU_ITEMS = [
  { id: 1, name: "Pizza", price: 199 },
  { id: 2, name: "Burger", price: 99 },
  { id: 3, name: "Sandwich", price: 70 },
  { id: 4, name: "Coffee", price: 45 },
  { id: 5, name: "Juice", price: 60 },
  { id: 6, name: "Idli", price: 30 },
  { id: 7, name: "Dosa", price: 35 },
  { id: 8, name: "Puri", price: 40 },
  { id: 9, name: "Vada", price: 35 },
  { id: 10, name: "Parota", price: 50 },


];

export default function MenuGrid({ addToCart }) {
  return (
    <div className="menu-section">
      {/* 🔹 MENU HEADER */}
      <h2 className="menu-title">🍽️ Available Menu</h2>

      <div className="menu-grid">
        {MENU_ITEMS.map(item => (
          <MenuCard
            key={item.id}
            item={item}
            addToCart={addToCart}
          />
        ))}
      </div>
    </div>
  );
}
